//! Turning a shorthand into the longhands Chrome stores, and turning them back.
//!
//! Chrome does not keep a shorthand in a declaration: `border: 1px solid red`
//! is seventeen entries, `style.length` is 17, and every read of `border` --
//! `getPropertyValue`, `cssText`, a style map -- is rebuilt from those
//! seventeen. The measurements behind the two directions are in
//! chrome_shorthands.zig, generated by tools/fingerprint/dump-css-shorthands.mjs.
//!
//! Everything here is table-driven. A shorthand the generator could not model
//! is absent from `expand`'s answer, and the caller keeps the declaration
//! whole -- one entry where Chrome has nine, which is a visible difference but
//! a smaller one than nine invented values.
const std = @import("std");

const table = @import("chrome_shorthands.zig");
const chrome_bounds = @import("chrome_bounds.zig");
const chrome_keywords = @import("chrome_keywords.zig");
const chrome_units = @import("chrome_units.zig");
const chrome_initial_values = @import("chrome_initial_values.zig");

const Allocator = std.mem.Allocator;

pub const Shorthand = table.Shorthand;

/// The longhands a shorthand became, parallel arrays in the order `item(i)`
/// answers.
pub const Expansion = struct {
    names: []const []const u8,
    values: []const []const u8,
};

/// The entry for a name this engine expands, or null for a longhand, an unknown
/// name, or a shorthand the generator left `.unmodelled`.
pub fn lookup(name: []const u8) ?Shorthand {
    const entry = table.shorthands.get(name) orelse return null;
    if (entry.kind == .unmodelled) return null;
    return entry;
}

/// The entry for a shorthand a COMPUTED view rebuilds from its longhands.
///
/// Not `lookup`, which declines every unmodelled entry, and not
/// `lookupJoinable`, which also answers for `font` and `border-image` -- those
/// two are still stored under their own name, so joining their longhands would
/// report the initial value over the author's own text. The four below are
/// expanded now (`grammarExpansion`), so their own name holds nothing and the
/// longhands are the only place the value is.
pub fn lookupComputedJoinable(name: []const u8) ?Shorthand {
    const entry = table.shorthands.get(name) orelse return null;
    if (entry.kind != .unmodelled) return entry;
    if (isColumns(entry) or isListStyle(entry) or isGridArea(entry) or isGridLinePair(entry) or isFontVariant(entry)) return entry;
    return null;
}

/// Like `lookup`, for the paths that only read a shorthand back rather than
/// store one: cssText, and the covering walk that builds it. `border-image`
/// answers here and not in `lookup`, because only half of it is modelled -- its
/// five longhands join to text Chrome writes, while a `border-image` the author
/// wrote is still kept whole rather than expanded.
pub fn lookupJoinable(name: []const u8) ?Shorthand {
    const entry = table.shorthands.get(name) orelse return null;
    if (entry.kind == .unmodelled and !isBorderImage(entry) and !isFont(entry) and
        !isColumns(entry) and !isListStyle(entry) and !isGridArea(entry) and
        !isGridLinePair(entry) and !isFontVariant(entry)) return null;
    return entry;
}

/// The six CSS system font keywords, and the one expansion Chrome gives all of
/// them. `font` itself stays `.unmodelled` -- its grammar is the thing no model
/// reproduced -- but these six are a closed set with a measured answer, so they
/// do not need the grammar to be handled.
///
/// Measured on Chrome 151 (probes/expr-b55-system-fonts.js,
/// results/b55-sysfont-chrome{,-headed}.json): all six expand identically, and
/// headed and headless agree exactly. `font-variant` is not in the list because
/// its longhands' initial values already answer `normal`, which is what Chrome
/// answers -- storing it would be reaching past what was measured.
///
/// Why it matters beyond tidiness: Kasada writes all six in one burst at
/// x-hyatt, `setAttribute('style', 'font: caption !important')` through
/// `status-bar`, and reads four numbers back. This engine answered the keyword
/// itself for `font`, which no browser produces.
const system_font_keywords = [_][]const u8{ "caption", "icon", "menu", "message-box", "small-caption", "status-bar" };
const system_font_names = [_][]const u8{ "font-style", "font-weight", "font-stretch", "font-size", "line-height", "font-family" };
const system_font_values = [_][]const u8{ "normal", "400", "100%", "16px", "normal", "Arial" };

/// What `font` reads back as once a system keyword expanded. Chrome rebuilds the
/// shorthand from the longhands; this engine keeps an unmodelled shorthand
/// whole, so the text has to be stored beside them.
pub const system_font_shorthand = "16px Arial";

/// The expansion for `font: <system keyword>`, or null for anything else --
/// including every other `font` value, which stays whole as before.
pub fn systemFontExpansion(name: []const u8, value: []const u8) ?Expansion {
    if (!std.ascii.eqlIgnoreCase(name, "font")) return null;
    const trimmed = std.mem.trim(u8, value, &std.ascii.whitespace);
    for (system_font_keywords) |keyword| {
        if (std.ascii.eqlIgnoreCase(keyword, trimmed)) {
            return .{ .names = &system_font_names, .values = &system_font_values };
        }
    }
    return null;
}

/// The nineteen longhands `font` expands to when Chrome PARSES one, in the
/// order Chrome stores them. Not the table's `longhands` order -- that is what a
/// CSS-wide keyword gives, measured, and the two differ from the third name on.
///
/// Read off Chrome 151 rather than derived: `style.length` and the indexed names
/// ARE Chrome's expansion, because Chrome keeps no shorthand in a declaration.
/// Sixteen accepted values give these nineteen names in this order every time
/// (probes/expr-b81-font-expansion.js, results/b81-fontexp-chrome.json).
const font_names = [_][]const u8{
    "font-style",            "font-variant-caps",       "font-variant-ligatures",
    "font-variant-numeric",  "font-variant-east-asian", "font-variant-alternates",
    "font-size-adjust",      "font-language-override",  "font-kerning",
    "font-optical-sizing",   "font-feature-settings",   "font-variation-settings",
    "font-variant-position", "font-variant-emoji",      "font-weight",
    "font-stretch",          "font-size",               "line-height",
    "font-family",
};

/// What each of the nineteen holds when the shorthand does not name it. The
/// grammar reaches only seven of them; the other twelve are reset to their own
/// initial values, which is why `font-size-adjust` is `none` and the two
/// `auto`s are not `normal`. Same reading.
const font_initials = [_][]const u8{
    "normal", "normal", "normal",
    "normal", "normal", "normal",
    "none",   "normal", "auto",
    "auto",   "normal", "normal",
    "normal", "normal", "normal",
    "normal", "",       "normal",
    "",
};

const font_style_at = 0;
const font_variant_at = 1;
const font_weight_at = 14;
const font_stretch_at = 15;
const font_size_at = 16;
const line_height_at = 17;
const font_family_at = 18;

/// `<font-style>`, `<font-variant-css2>` and `<font-stretch-css3>` as the `font`
/// grammar takes them -- closed sets, so they are written out rather than asked
/// of the generated tables. `font-variant-caps` on its own takes more than these
/// two (`all-small-caps` and four others); the shorthand does not, and using the
/// longhand's table here would accept values Chrome refuses.
const font_style_words = [_][]const u8{ "normal", "italic", "oblique" };
const font_variant_words = [_][]const u8{ "normal", "small-caps" };
const font_stretch_words = [_][]const u8{
    "normal",         "ultra-condensed", "extra-condensed", "condensed",
    "semi-condensed", "semi-expanded",   "expanded",        "extra-expanded",
    "ultra-expanded",
};
const font_weight_words = [_][]const u8{ "normal", "bold", "bolder", "lighter" };
/// `<absolute-size>` and `<relative-size>`, the two size keyword families.
const font_size_words = [_][]const u8{
    "xx-small", "x-small", "small",    "medium",
    "large",    "x-large", "xx-large", "xxx-large",
    "larger",   "smaller",
};

/// Three outcomes, because two of them are not the same thing.
///
/// `font` is unlike every other unmodelled shorthand in that Chrome does not
/// keep an invalid one whole -- it throws the declaration away. `font: 13px`
/// with no family leaves `style.length` at 0, where this engine used to leave
/// one entry holding `13px`. So a decline has to say which kind it is, and
/// `null` is reserved for the third: a value this cannot judge, which stays
/// whole rather than becoming a guess.
pub const FontShorthand = union(enum) {
    /// A parsed `font`: the nineteen longhands, in Chrome's parsed order. What
    /// `font` itself reads back as is `fontShorthandText` of these values AFTER
    /// the caller has normalised them -- `font: 0 serif` stores `0px` and reads
    /// back `0px serif`, so rebuilding from the author's raw token would be one
    /// character wrong.
    parsed: Expansion,
    /// A CSS-wide keyword, which reaches all nineteen as itself -- in the
    /// table's order, which is not the parsed one. `font` reads back as the
    /// keyword rather than as nineteen of them joined.
    wide: struct { expansion: Expansion, keyword: []const u8 },
    refused,
};

/// What Chrome stores for a `font` shorthand it parses.
///
/// The cost of not doing this was measured: with `style="font:<n>px serif"` over
/// eighteen sizes this engine answered the SAME box width for every one of them
/// -- the default font's -- while its own `measureText` answered each size
/// correctly, because the shorthand reached the canvas font and never the
/// cascade (probes/expr-b81-font-shorthand-layout.js). Computed `font-size` and
/// `font-family` were wrong on every page that sets `font`, and Cloudflare reads
/// 736 computed property names one at a time.
///
/// The grammar, and where each boundary came from
/// (probes/expr-b83-font-refusals.js measured all of it):
///
///   * the leading parts are a `||` group, so they may come in any order and any
///     may be left out. Each may appear once -- `bold bold 16px serif` and
///     `italic oblique 16px serif` are both refused -- except that `normal`
///     repeats freely, since `normal normal normal normal 16px serif` is
///     accepted and every slot's initial is `normal` anyway.
///   * everything after the size (and its optional `/ <line-height>`) is the
///     family, whatever it looks like: `16px bold serif` is accepted with a
///     family of `bold serif`, not a weight of `bold`.
///   * the weight range is 1 to 1000 INCLUSIVE and takes fractions: 1, 1000 and
///     350.5 are accepted, 0, -1 and 1001 are refused.
///   * a size of `0` is accepted and a negative one is refused.
///   * both halves of the mandatory tail are required: no size, no family, or
///     neither, and Chrome drops the declaration. So does a dangling `/`.
///
/// What this declines to judge, and why declining is the safe direction: a value
/// carrying `var()`, a function like `calc()`, or a comment. Chrome expands all
/// three -- and reorders the arithmetic inside `calc(1px + 1em)` to
/// `calc(1em + 1px)` while it is there, which is exactly the sort of detail a
/// guess gets wrong. Keeping the declaration whole leaves the page working with
/// one entry where Chrome has nineteen; inventing nineteen wrong ones does not.
pub fn fontExpansion(arena: Allocator, name: []const u8, value: []const u8) !?FontShorthand {
    if (!std.ascii.eqlIgnoreCase(name, "font")) return null;
    const trimmed = std.mem.trim(u8, value, &std.ascii.whitespace);
    if (trimmed.len == 0) return null;
    // The six system keywords are their own measured expansion and are handled
    // ahead of this; a CSS-wide keyword reaches all nineteen as itself, in the
    // table's order rather than the parsed one.
    if (systemFontExpansion(name, trimmed) != null) return null;
    if (cssWide(trimmed)) |keyword| {
        const entry = table.shorthands.get("font") orelse return null;
        const values = try arena.alloc([]const u8, entry.longhands.len);
        @memset(values, keyword);
        return .{ .wide = .{
            .expansion = .{ .names = entry.longhands, .values = values },
            .keyword = keyword,
        } };
    }
    if (!fontJudgeable(trimmed)) return null;

    var slots: [font_names.len][]const u8 = font_initials;
    var seen_style = false;
    var seen_variant = false;
    var seen_weight = false;
    var seen_stretch = false;

    var parts = Components.init(trimmed);
    parts.slash = true;

    // The leading `||` group, up to the first token that is a font size.
    var size: ?[]const u8 = null;
    while (parts.next()) |token| {
        if (isFontSize(token)) {
            size = token;
            break;
        }
        if (cssWide(token) != null) return .refused;
        if (std.mem.eql(u8, token, "/")) return .refused;
        if (std.ascii.eqlIgnoreCase(token, "normal")) continue;
        if (listedIgnoreCase(&font_style_words, token)) {
            if (seen_style) return .refused;
            seen_style = true;
            // `oblique <angle>` is one part in two tokens, and the angle is
            // stored with it: Chrome answers `font-style: oblique 20deg`.
            if (std.ascii.eqlIgnoreCase(token, "oblique")) {
                const save = parts.index;
                if (parts.next()) |next| {
                    if (classify(next).angle) {
                        slots[font_style_at] = try std.fmt.allocPrint(arena, "{s} {s}", .{ token, next });
                        continue;
                    }
                }
                parts.index = save;
            }
            slots[font_style_at] = token;
            continue;
        }
        if (listedIgnoreCase(&font_variant_words, token)) {
            if (seen_variant) return .refused;
            seen_variant = true;
            slots[font_variant_at] = token;
            continue;
        }
        if (isFontWeight(token)) |weight| {
            if (seen_weight) return .refused;
            seen_weight = true;
            slots[font_weight_at] = weight orelse return .refused;
            continue;
        }
        if (listedIgnoreCase(&font_stretch_words, token)) {
            if (seen_stretch) return .refused;
            seen_stretch = true;
            slots[font_stretch_at] = token;
            continue;
        }
        // An identifier the grammar does not name, before the size: Chrome
        // drops the declaration (`wibble 16px serif`).
        return .refused;
    }
    slots[font_size_at] = size orelse return .refused;
    if (negative(slots[font_size_at])) return .refused;

    // `/ <line-height>`, if the next token is the slash. `Components` hands the
    // slash back on its own, so `16px/1.4` and `16px / 1.4` are the same three
    // tokens.
    var family_from = parts.index;
    if (parts.next()) |token| {
        if (std.mem.eql(u8, token, "/")) {
            const line = parts.next() orelse return .refused;
            if (std.mem.eql(u8, line, "/")) return .refused;
            if (cssWide(line) != null) return .refused;
            slots[line_height_at] = line;
            family_from = parts.index;
        } else {
            parts.index = family_from;
        }
    }

    const family = std.mem.trim(u8, trimmed[family_from..], &std.ascii.whitespace);
    if (family.len == 0 or !isFontFamily(family)) return .refused;
    slots[font_family_at] = family;

    const values = try arena.alloc([]const u8, font_names.len);
    @memcpy(values, &slots);
    return .{ .parsed = .{ .names = &font_names, .values = values } };
}

/// Whether `entry` is the `font` shorthand, told from its shape the way
/// `isBorderImage` is: nineteen longhands opening with `font-style`, which no
/// other shorthand comes close to. The table still calls it `.unmodelled`,
/// because only half of it is modelled here -- `expand` still declines it and
/// `fontExpansion` handles the parsing -- but the JOINING half has to answer,
/// or a declaration that expanded reads back as nineteen longhands where Chrome
/// writes `font: 12px MyFont`.
fn isFont(entry: Shorthand) bool {
    return entry.kind == .unmodelled and
        entry.longhands.len == 19 and
        std.mem.eql(u8, entry.longhands[0], "font-style") and
        std.mem.eql(u8, entry.longhands[12], "font-family");
}

/// Where the seven longhands the `font` grammar names sit in the TABLE's order,
/// which is the order `join` and `covering` hand values over in -- not the
/// parsed order `font_names` has. The two differ from the third name on.
const font_join_style = 0;
const font_join_variant = 2;
const font_join_weight = 8;
const font_join_stretch = 9;
const font_join_size = 10;
const font_join_line_height = 11;
const font_join_family = 12;

/// `font` as Chrome writes it back, given its nineteen longhands in table order.
/// The all-CSS-wide case is answered before this is reached, so `font: inherit`
/// is `inherit` rather than nineteen of them.
fn fontJoin(arena: Allocator, values: []const []const u8) ![]const u8 {
    return fontShorthandText(arena, &.{
        values[font_join_style],  values[font_join_variant],
        values[font_join_weight], values[font_join_stretch],
        values[font_join_size],   values[font_join_line_height],
        values[font_join_family],
    });
}

/// Whether what is left after the size can be a family list at all. A
/// `<family-name>` is a string or a run of IDENTIFIERS, so a token that opens
/// with a digit is not one -- and that is the whole reason `font: 0 16px serif`
/// is refused while `font: 0 serif` and `font: 16px bold serif` are both
/// accepted (measured, expr-b83-font-refusals.js). Taking `0` as the size there
/// leaves `16px serif` as the family, and `16px` is a dimension rather than an
/// identifier, so the declaration has nowhere left to go.
fn isFontFamily(text: []const u8) bool {
    var rest = text;
    while (rest.len > 0) {
        const comma = std.mem.indexOfScalar(u8, rest, ',') orelse rest.len;
        const entry = std.mem.trim(u8, rest[0..comma], &std.ascii.whitespace);
        if (entry.len == 0) return false;
        if (entry[0] != '"' and entry[0] != '\'') {
            var words = std.mem.tokenizeAny(u8, entry, &std.ascii.whitespace);
            while (words.next()) |word| {
                if (!identifierStart(word)) return false;
            }
        }
        if (comma == rest.len) break;
        rest = rest[comma + 1 ..];
    }
    return true;
}

/// Whether the token opens the way a CSS identifier does. Digits and a sign are
/// out, and so is a `-` followed by a digit; everything else is left alone,
/// since an identifier may hold escapes and non-ASCII.
fn identifierStart(word: []const u8) bool {
    if (word.len == 0) return false;
    switch (word[0]) {
        '0'...'9', '+', '.' => return false,
        '-' => return word.len > 1 and !std.ascii.isDigit(word[1]),
        else => return true,
    }
}

/// `font` as Chrome rebuilds it, given the seven parts the grammar names in
/// grammar order: style, variant, weight, stretch, size, line-height, family.
///
/// Measured on sixteen values (probes/expr-b81-font-expansion.js): a fixed order
/// regardless of how the author wrote them, so `bold italic 16px serif` reads
/// back `italic bold 16px serif`; every part holding `normal` left out; spaces
/// around the slash (`16px / 1.4 serif`); and no slash at all when the line
/// height is `normal`, so `16px/normal serif` reads back `16px serif`. The
/// stored token is echoed rather than a computed one -- `bold` stays `bold` and
/// `700` stays `700`.
fn fontShorthandText(arena: Allocator, parts: []const []const u8) ![]const u8 {
    std.debug.assert(parts.len == 7);
    var out: std.ArrayList(u8) = .empty;
    for (parts[0..4]) |part| {
        if (std.ascii.eqlIgnoreCase(part, "normal")) continue;
        if (out.items.len > 0) try out.append(arena, ' ');
        try out.appendSlice(arena, part);
    }
    if (out.items.len > 0) try out.append(arena, ' ');
    try out.appendSlice(arena, parts[4]);
    if (!std.ascii.eqlIgnoreCase(parts[5], "normal")) {
        try out.appendSlice(arena, " / ");
        try out.appendSlice(arena, parts[5]);
    }
    try out.append(arena, ' ');
    try out.appendSlice(arena, parts[6]);
    return out.items;
}

/// Whether the value is one this engine will read a `font` grammar out of. Not
/// `judgeable`: that one refuses a comma, and a family list is commas by
/// definition. What it refuses instead is what a guess would get wrong -- a
/// comment, and any function, `var()` and `calc()` included.
fn fontJudgeable(value: []const u8) bool {
    if (std.mem.indexOf(u8, value, "/*") != null) return false;
    if (std.mem.indexOfScalar(u8, value, '(') != null) return false;
    return true;
}

fn listedIgnoreCase(words: []const []const u8, token: []const u8) bool {
    for (words) |word| {
        if (std.ascii.eqlIgnoreCase(word, token)) return true;
    }
    return false;
}

/// Whether the token sits in the size slot. The two keyword families, or a
/// number-led length or percentage the `font-size` longhand's own measured
/// grammar accepts.
fn isFontSize(token: []const u8) bool {
    if (listedIgnoreCase(&font_size_words, token)) return true;
    if (token.len == 0) return false;
    switch (token[0]) {
        '0'...'9', '.', '+', '-' => {},
        else => return false,
    }
    return !refusesLonghand("font-size", token);
}

/// Null when the token is not a weight at all; a null payload when it is one
/// Chrome refuses. The range is 1 to 1000 inclusive and takes fractions --
/// measured either side, and `0` is refused rather than clamped.
fn isFontWeight(token: []const u8) ??[]const u8 {
    if (listedIgnoreCase(&font_weight_words, token)) return token;
    const number = std.fmt.parseFloat(f64, token) catch return null;
    if (number < 1 or number > 1000) return @as(?[]const u8, null);
    return token;
}

/// What Chrome stores for `name: value`, or null when the value does not fit
/// the shorthand's grammar. Null means "keep it whole": under-expanding leaves
/// a page working, where a wrong expansion answers values Chrome never had.
pub fn expand(arena: Allocator, entry: Shorthand, value: []const u8) !?Expansion {
    // A CSS-wide keyword reaches every longhand as itself -- and nine
    // shorthands enumerate them in a different order for that case, which is
    // why `wide_longhands` exists.
    if (cssWide(std.mem.trim(u8, value, &std.ascii.whitespace))) |keyword| {
        const names = if (entry.wide_longhands.len > 0) entry.wide_longhands else entry.longhands;
        const values = try arena.alloc([]const u8, names.len);
        @memset(values, keyword);
        return .{ .names = names, .values = values };
    }

    if (entry.kind == .layers) return layerExpand(arena, entry, value);
    if (entry.kind == .corners) return cornersExpand(arena, entry, value);

    const values = try arena.alloc([]const u8, entry.longhands.len);
    switch (entry.kind) {
        .unmodelled => return null,
        .layers, .corners => unreachable,
        .alias => values[0] = translated(entry, value),
        .presets => {
            const hit = preset(entry, value) orelse return null;
            @memcpy(values, hit[1]);
        },
        .box4, .box2 => {
            var written: [4][]const u8 = undefined;
            var count: usize = 0;
            var box = Components.init(value);
            while (box.next()) |component| : (count += 1) {
                if (count == written.len) return null;
                written[count] = component;
            }
            if (!box.exhausted()) return null;
            const mapped = boxRule(written[0..count], values.len) orelse return null;
            @memcpy(values, mapped[0..values.len]);
        },
        .components => {
            var slots: [max_group][]const u8 = undefined;
            @memset(slots[0..entry.group], "");
            var rest = Components.init(value);
            while (rest.next()) |component| {
                const slot = place(entry, component, slots[0..entry.group]) orelse return null;
                slots[slot] = component;
            }
            if (!rest.exhausted()) return null;
            for (values, 0..) |*out, i| {
                const held = if (i < entry.group * entry.groups) slots[slotOf(entry, i)] else "";
                out.* = if (held.len == 0) entry.fillers[i] else held;
            }
        },
    }
    return .{ .names = entry.longhands, .values = values };
}

/// What reading the shorthand back answers, given each longhand's stored value
/// in `entry.longhands` order. "" is a real answer, not a failure: Chrome
/// answers nothing for a `border` whose components all hold their initial
/// value, because it cannot be written as one shorthand.
pub fn join(arena: Allocator, entry: Shorthand, values: []const []const u8) ![]const u8 {
    return joinKeeping(arena, entry, values, false);
}

/// `join` with the option to write every component, whatever it holds. The
/// border family's computed serialisation does exactly that: `border` off a
/// computed view is `0px none rgb(0, 0, 0)` where the same declaration read off
/// `el.style` drops the `none`. Measured across five declaration states with
/// tools/fingerprint/scratch/expr-computed-border-join.js.
pub fn joinKeeping(arena: Allocator, entry: Shorthand, values: []const []const u8, keep_all: bool) ![]const u8 {
    std.debug.assert(values.len == entry.longhands.len);

    // Every longhand holding the same CSS-wide keyword reads back as it.
    if (cssWide(values[0])) |keyword| {
        for (values[1..]) |value| {
            if (!std.ascii.eqlIgnoreCase(value, keyword)) break;
        } else return keyword;
    }

    if (entry.kind == .layers) return layerJoin(arena, entry, values);
    if (entry.kind == .corners) return cornersJoin(arena, values);

    if (isBorderImage(entry)) return borderImageJoin(arena, values);
    if (isFont(entry)) return fontJoin(arena, values);
    if (isColumns(entry)) return columnsJoin(arena, values);
    if (isListStyle(entry)) return listStyleJoin(arena, values, keep_all);
    if (isGridArea(entry)) return gridAreaJoin(arena, values);
    if (isGridLinePair(entry)) return gridLinePairJoin(arena, values);
    if (isFontVariant(entry)) return fontVariantJoin(arena, values);

    switch (entry.kind) {
        .unmodelled => return "",
        .layers, .corners => unreachable,
        .alias => {
            for (entry.reads) |pair| {
                if (std.ascii.eqlIgnoreCase(pair[0], values[0])) return pair[1];
            }
            return values[0];
        },
        .presets => {
            for (entry.presets) |row| {
                for (row[1], values) |want, got| {
                    if (!std.ascii.eqlIgnoreCase(want, got)) break;
                } else return row[2];
            }
            return "";
        },
        .box4, .box2 => {
            const short = boxForm(values);
            return std.mem.join(arena, " ", short);
        },
        .components => {
            // A repeat that disagrees with the first group cannot be written as
            // one shorthand at all.
            for (0..entry.group * entry.groups) |i| {
                const mirror = representative(entry, slotOf(entry, i));
                if (!std.ascii.eqlIgnoreCase(values[i], values[mirror])) return "";
            }
            for (entry.group * entry.groups..values.len) |i| {
                if (!std.ascii.eqlIgnoreCase(values[i], entry.fillers[i])) return "";
            }

            var kept: std.ArrayList([]const u8) = .empty;
            defer kept.deinit(arena);
            for (0..entry.group) |n| {
                const slot = if (entry.order.len > 0) entry.order[n] else n;
                const held = values[representative(entry, slot)];
                if (!keep_all and dropped(entry.omit[slot], held)) continue;
                try kept.append(arena, held);
            }
            if (kept.items.len == 0) return entry.empty orelse "";
            return std.mem.join(arena, " ", kept.items);
        },
    }
}

/// The shorthands covering `name`, widest first, for putting cssText back
/// together: `border-top-width` is reachable through `border`, `border-width`
/// and `border-top`, and the widest one that has all its longhands present is
/// the one Chrome writes. A -webkit- spelling is never one of them -- Chrome
/// writes the unprefixed name.
pub fn covering(name: []const u8, buf: [][]const u8) [][]const u8 {
    var found: usize = 0;
    for (table.shorthands.keys(), table.shorthands.values()) |key, entry| {
        if (key[0] == '-') continue;
        if (entry.kind == .unmodelled and !isBorderImage(entry) and !isFont(entry) and
            !isColumns(entry) and !isListStyle(entry) and !isGridArea(entry) and
            !isGridLinePair(entry) and !isFontVariant(entry)) continue;
        if (entry.longhands.len == 1 and std.mem.eql(u8, entry.longhands[0], key)) continue;
        for (entry.longhands) |longhand| {
            if (!std.mem.eql(u8, longhand, name)) continue;
            if (found == buf.len) break;
            buf[found] = key;
            found += 1;
            break;
        }
    }
    const out = buf[0..found];
    std.mem.sort([]const u8, out, {}, struct {
        fn wider(_: void, a: []const u8, b: []const u8) bool {
            const left = table.shorthands.get(a).?.longhands.len;
            const right = table.shorthands.get(b).?.longhands.len;
            return if (left == right) std.mem.lessThan(u8, a, b) else left > right;
        }
    }.wider);
    return out;
}

// --- the border-image grammar -------------------------------------------
//
// `border-image` is the one shorthand with a real grammar the generator could
// not reproduce, so the table carries it as `.unmodelled`. Writing it back is
// still needed, and for two reasons rather than one: it is a covering shorthand
// of its own five longhands, and it is the last link of `border`'s fallback
// chain -- a `border` whose four widths disagree writes border-width,
// border-style, border-color and border-image instead of itself, and the chain
// is all-or-nothing.
//
// Only the joining half is modelled here. A `border-image` the author wrote
// directly is still kept whole, which is what this engine did before.

/// Whether `entry` is the `border-image` shorthand. The table has no name to
/// match on by the time `join` sees an entry, and its five longhands are a
/// shape no other shorthand shares.
fn isBorderImage(entry: Shorthand) bool {
    return entry.kind == .unmodelled and
        entry.longhands.len == 5 and
        std.mem.eql(u8, entry.longhands[0], "border-image-source");
}

/// `border-image` as Chrome writes it, given its five longhands in table order.
/// Measured with tools/fingerprint/probes/expr-border-image-serialize.js: the
/// four components after the source are written only when at least one of them
/// is off its initial value, and then all four are, slashes and all --
/// `border-image-slice: 30` alone reads back `url("a") 30 / 1 / 0 stretch`.
/// With all four initial only the source is written, whatever the author
/// spelled: `border-image: url(a) 100%` comes back `url("a")`.
fn borderImageJoin(arena: Allocator, values: []const []const u8) ![]const u8 {
    for (values[1..], 1..) |held, i| {
        const initial = chrome_initial_values.initial.get(border_image_longhands[i]) orelse return "";
        if (!std.ascii.eqlIgnoreCase(held, initial)) {
            return std.mem.concat(arena, u8, &.{
                values[0], " ", values[1], " / ", values[2], " / ", values[3], " ", values[4],
            });
        }
    }
    return values[0];
}

const border_image_longhands = [_][]const u8{
    "border-image-source",
    "border-image-slice",
    "border-image-width",
    "border-image-outset",
    "border-image-repeat",
};

// --- the corner grammar -------------------------------------------------

/// `border-radius` is the one four-value box shorthand carrying a `/`, and the
/// `/` is what makes it its own kind: it is two box lists, one of horizontal
/// radii and one of vertical, distributed over four corner longhands that each
/// hold a *pair*. Measured by tools/fingerprint/probes/probe-css16.js.
fn cornersExpand(arena: Allocator, entry: Shorthand, value: []const u8) !?Expansion {
    var sides: [2][4][]const u8 = undefined;
    var written: [2]usize = .{ 0, 0 };
    var half: usize = 0;
    var walk = Components{ .text = std.mem.trim(u8, value, &std.ascii.whitespace), .slash = true };
    while (walk.next()) |component| {
        if (component.len == 1 and component[0] == '/') {
            // A second `/`, and one with nothing before it, are both declines.
            if (half == 1 or written[0] == 0) return null;
            half = 1;
            continue;
        }
        // A radius is a length or a percentage and nothing else, so `auto`,
        // `none` and a bare number are declines rather than four invented
        // corners. All four longhands take the same classes, measured, which is
        // why the first stands for the lot.
        if (!accepts(entry.longhands[0], component)) return null;
        if (written[half] == sides[half].len) return null;
        sides[half][written[half]] = component;
        written[half] += 1;
    }
    if (!walk.exhausted()) return null;
    // A `/` with nothing after it is a decline too.
    if (written[0] == 0 or (half == 1 and written[1] == 0)) return null;

    // The legacy WebKit spelling reads *exactly* two components as
    // horizontal-then-vertical rather than top-left-then-top-right, which is
    // the one place the two parsers disagree: `-webkit-border-radius: 10px
    // 20px` is `10px / 20px` where `border-radius: 10px 20px` is itself.
    if (half == 0 and entry.legacy_pair and written[0] == 2) {
        sides[1][0] = sides[0][1];
        written = .{ 1, 1 };
        half = 1;
    }

    const horizontal = boxRule(sides[0][0..written[0]], 4) orelse return null;
    const vertical = if (half == 0)
        horizontal
    else
        boxRule(sides[1][0..written[1]], 4) orelse return null;

    const values = try arena.alloc([]const u8, entry.longhands.len);
    if (values.len != horizontal.len) return null;
    for (values, 0..) |*out, i| {
        // A corner holds the pair, folded to one when the two agree -- which is
        // why a value with no `/` leaves every corner holding one component.
        out.* = if (std.ascii.eqlIgnoreCase(horizontal[i], vertical[i]))
            horizontal[i]
        else
            try std.mem.join(arena, " ", &.{ horizontal[i], vertical[i] });
    }
    return .{ .names = entry.longhands, .values = values };
}

/// What reading a corner shorthand back answers. Each list is elided by the box
/// rule *independently*, and the `/` goes only when the two come out identical:
/// `10px 20px / 10px 20px` reads `10px 20px` where `10px 10px / 20px 20px`
/// reads `10px / 20px`.
fn cornersJoin(arena: Allocator, values: []const []const u8) ![]const u8 {
    var horizontal: [4][]const u8 = undefined;
    var vertical: [4][]const u8 = undefined;
    if (values.len != horizontal.len) return "";
    for (values, 0..) |held, i| {
        var walk = Components.init(held);
        const first = walk.next() orelse return "";
        const second = walk.next() orelse first;
        // A corner holding anything but one component or two cannot have come
        // from this shorthand, so it cannot be written as one either.
        if (walk.next() != null or !walk.exhausted()) return "";
        horizontal[i] = first;
        vertical[i] = second;
    }

    const across = try std.mem.join(arena, " ", boxForm(&horizontal));
    const down = try std.mem.join(arena, " ", boxForm(&vertical));
    if (std.ascii.eqlIgnoreCase(across, down)) return across;
    return std.mem.concat(arena, u8, &.{ across, " / ", down });
}

// --- the layer grammar --------------------------------------------------

/// `background` is not a run of components. It is a comma-separated list of
/// layers, and inside a layer one position fills *two* longhands out of one to
/// four components, a `/` introduces a size and may only sit straight after
/// the position, one box component lands on both the origin and the clip, and
/// the colour belongs to the whole value rather than to a layer -- which is why
/// `background: red, blue` does not parse and `url(a), red` does. Every part of
/// that was measured; see chrome_shorthands.zig.
fn layerExpand(arena: Allocator, entry: Shorthand, value: []const u8) !?Expansion {
    const total = entry.longhands.len;
    const width = entry.layer_width;

    var texts: std.ArrayList([]const u8) = .empty;
    defer texts.deinit(arena);
    var split = Layers.init(value);
    while (split.next()) |layer| {
        if (layer.len == 0) return null;
        try texts.append(arena, layer);
    }
    if (texts.items.len == 0) return null;

    var layers: std.ArrayList([]const ?[]const u8) = .empty;
    defer layers.deinit(arena);
    for (texts.items, 0..) |text, n| {
        const last = n == texts.items.len - 1;
        const parsed = try parseLayer(arena, entry, text, last) orelse return null;
        // A shared slot is the whole value's, so only the last layer may reach
        // one: `url(a) blue, url(b)` does not parse where `url(a), url(b) blue`
        // does.
        if (!last) {
            for (parsed[width..]) |held| {
                if (held != null) return null;
            }
        }
        try layers.append(arena, parsed);
    }

    const values = try arena.alloc([]const u8, total);
    for (values, 0..) |*out, s| {
        if (s >= width) {
            out.* = layers.items[layers.items.len - 1][s] orelse entry.fillers[s];
            continue;
        }
        var list: std.ArrayList([]const u8) = .empty;
        defer list.deinit(arena);
        for (layers.items) |layer| {
            try list.append(arena, layer[s] orelse entry.fillers[s]);
        }
        out.* = try std.mem.join(arena, ", ", list.items);
    }
    return .{ .names = entry.longhands, .values = values };
}

/// One layer's components distributed over the slots, `null` where the value
/// never mentioned one, or null for the whole layer when it does not fit -- in
/// which case the caller keeps the declaration whole.
fn parseLayer(arena: Allocator, entry: Shorthand, text: []const u8, last: bool) !?[]?[]const u8 {
    const slots = try arena.alloc(?[]const u8, entry.longhands.len);
    @memset(slots, null);

    var found: std.ArrayList([]const u8) = .empty;
    defer found.deinit(arena);
    var walk = Components{ .text = std.mem.trim(u8, text, &std.ascii.whitespace), .slash = true };
    while (walk.next()) |component| try found.append(arena, component);
    if (!walk.exhausted()) return null;
    const toks = found.items;

    const axes = entry.axes;
    var i: usize = 0;
    var after_position = false;
    var mirrored = false;
    while (i < toks.len) {
        const token = toks[i];
        for (entry.refuse) |bad| {
            if (std.ascii.eqlIgnoreCase(bad, token)) return null;
        }
        if (token.len == 1 and token[0] == '/') {
            // The size is one of the two slots that take a pair, so
            // `left top / 10px 20px` is a layer and not a decline. The pair
            // goes to the longhand whole and is shortened there.
            if (!after_position or entry.size_slot == table.no_slot) return null;
            if (slots[entry.size_slot] != null) return null;
            const run = runLength(entry, toks[i + 1 ..], entry.size_slot);
            if (run == 0) return null;
            slots[entry.size_slot] = try runText(arena, toks[i + 1 ..], run);
            i += 1 + run;
            after_position = false;
            continue;
        }
        // The box pair. One component fills both -- `background: padding-box`
        // moves the origin *and* the clip -- and a second takes the clip over.
        // `text` is a clip and not an origin, which is why `text border-box`
        // lands the other way round from how it was written.
        if (entry.boxes[0] != table.no_slot and boxToken(entry, token)) {
            const first = entry.boxes[0];
            const second = entry.boxes[1];
            if (slots[first] == null and accepts(entry.longhands[first], token)) {
                slots[first] = token;
                if (slots[second] == null) {
                    slots[second] = token;
                    mirrored = true;
                }
            } else if (accepts(entry.longhands[second], token) and
                (slots[second] == null or mirrored))
            {
                slots[second] = token;
                mirrored = false;
            } else return null;
            after_position = false;
            i += 1;
            continue;
        }
        if (axes[0] != table.no_slot and slots[axes[0]] == null and slots[axes[1]] == null) {
            // Up to four components, longest first: `left 10px top 20px` is one
            // position where `left 10px no-repeat` is a two-component one
            // followed by a repeat.
            var room: usize = 0;
            while (i + room < toks.len and !(toks[i + room].len == 1 and toks[i + room][0] == '/')) {
                room += 1;
            }
            var k = @min(@as(usize, 4), room);
            const placed = while (k >= 1) : (k -= 1) {
                var pair: [2][]const u8 = undefined;
                if (try positionSlots(arena, entry, toks[i .. i + k], &pair)) {
                    slots[axes[0]] = pair[0];
                    slots[axes[1]] = pair[1];
                    break true;
                }
            } else false;
            if (placed) {
                i += k;
                after_position = true;
                continue;
            }
        }
        const order = entry.longhands.len;
        var slot: usize = 0;
        const placed = while (slot < order) : (slot += 1) {
            if (slots[slot] != null) continue;
            if (slot == axes[0] or slot == axes[1]) continue;
            if (slot == entry.boxes[0] or slot == entry.boxes[1]) continue;
            if (slot == entry.size_slot) continue;
            if (slot >= entry.layer_width and !last) continue;
            // The repeat is the other slot that takes a pair, which is what
            // makes `repeat no-repeat` one component of the layer rather than
            // two the model has nowhere to put.
            const run = runLength(entry, toks[i..], slot);
            if (run == 0) continue;
            slots[slot] = try runText(arena, toks[i..], run);
            break run;
        } else 0;
        if (placed == 0) return null;
        after_position = false;
        i += placed;
    }
    return slots;
}

/// How many of the components at the head of `toks` the slot takes as one
/// value: two where the table measured the longhand keeping a pair, one
/// everywhere else, and zero when the slot will not take even the first.
fn runLength(entry: Shorthand, toks: []const []const u8, slot: usize) usize {
    if (toks.len == 0 or isSlash(toks[0])) return 0;
    if (!accepts(entry.longhands[slot], toks[0])) return 0;
    if (toks.len < 2 or isSlash(toks[1])) return 1;
    if (std.mem.indexOfScalar(u8, entry.pairs, @intCast(slot)) == null) return 1;
    if (!accepts(entry.longhands[slot], toks[1])) return 1;
    return 2;
}

fn runText(arena: Allocator, toks: []const []const u8, run: usize) ![]const u8 {
    if (run == 1) return toks[0];
    return std.mem.join(arena, " ", toks[0..run]);
}

fn isSlash(token: []const u8) bool {
    return token.len == 1 and token[0] == '/';
}

/// Whether a component belongs to the box pair at all, which is what keeps a
/// keyword only the clip takes from being handed to the generic placement.
fn boxToken(entry: Shorthand, token: []const u8) bool {
    return accepts(entry.longhands[entry.boxes[0]], token) or
        accepts(entry.longhands[entry.boxes[1]], token);
}

/// The two values a position leaves on its axes. One component fills both --
/// the axis the page did not write is left holding `implied` -- two keywords
/// may come in either order where a length fixes it, and three or four
/// components are two `edge [offset]` groups.
fn positionSlots(
    arena: Allocator,
    entry: Shorthand,
    toks: []const []const u8,
    out: *[2][]const u8,
) !bool {
    const x = entry.longhands[entry.axes[0]];
    const y = entry.longhands[entry.axes[1]];
    if (toks.len == 1) {
        const takes_x = accepts(x, toks[0]);
        const takes_y = accepts(y, toks[0]);
        if (!takes_x and !takes_y) return false;
        out.* = if (!takes_x) .{ entry.implied, toks[0] } else .{ toks[0], entry.implied };
        return true;
    }
    if (toks.len == 2) {
        const first = toks[0];
        const second = toks[1];
        // `top right` is x=right y=top, and `10px left` does not parse: only
        // two keywords may swap.
        if (classify(first).identifier and classify(second).identifier) {
            const swap = (accepts(y, first) and !accepts(x, first)) or
                (accepts(x, second) and !accepts(y, second));
            if (swap) {
                if (!accepts(x, second) or !accepts(y, first)) return false;
                out.* = .{ second, first };
                return true;
            }
        }
        if (!accepts(x, first) or !accepts(y, second)) return false;
        out.* = .{ first, second };
        return true;
    }
    if (toks.len > 4) return false;
    const splits: [2][2]usize = if (toks.len == 3) .{ .{ 1, 2 }, .{ 2, 1 } } else .{ .{ 2, 2 }, .{ 0, 0 } };
    for (splits) |split| {
        if (split[0] + split[1] != toks.len) continue;
        var group: [2][]const u8 = undefined;
        var axis: [2]u8 = undefined;
        var ok = true;
        for (0..2) |g| {
            const start = if (g == 0) 0 else split[0];
            const run = toks[start .. start + split[g]];
            if (run.len == 1) {
                group[g] = run[0];
                const takes_x = accepts(x, run[0]);
                const takes_y = accepts(y, run[0]);
                axis[g] = if (takes_x and takes_y) 2 else if (takes_x) 0 else if (takes_y) 1 else 3;
            } else {
                // An offset may only follow an edge measured carrying one:
                // `left 10px` is a position and `center 10px` is not, which is
                // why `center 10px top` does not parse.
                const offset = classify(run[1]);
                if (!offset.length and !offset.percent) {
                    ok = false;
                    break;
                }
                group[g] = try std.mem.join(arena, " ", run);
                const takes_x = listed(entry.offsets[0], run[0]);
                const takes_y = listed(entry.offsets[1], run[0]);
                axis[g] = if (takes_x and takes_y) 2 else if (takes_x) 0 else if (takes_y) 1 else 3;
            }
            if (axis[g] == 3) {
                ok = false;
                break;
            }
        }
        if (!ok) continue;
        if (axis[0] == 0 and axis[1] != 0) {
            out.* = .{ group[0], group[1] };
        } else if (axis[0] == 1 and axis[1] != 1) {
            out.* = .{ group[1], group[0] };
        } else if (axis[0] == 2 and axis[1] == 1) {
            out.* = .{ group[0], group[1] };
        } else if (axis[0] == 2 and axis[1] == 0) {
            out.* = .{ group[1], group[0] };
        } else continue;
        return true;
    }
    return false;
}

fn listed(names: []const []const u8, token: []const u8) bool {
    for (names) |name| {
        if (std.ascii.eqlIgnoreCase(name, token)) return true;
    }
    return false;
}

/// Reading a layered shorthand back: every slot that is not at its dropped
/// value, in the order Chrome writes them, with the size behind a `/` and the
/// shared slots appended to the last layer.
fn layerJoin(arena: Allocator, entry: Shorthand, values: []const []const u8) ![]const u8 {
    const total = entry.longhands.len;
    const width = entry.layer_width;

    const lists = try arena.alloc([]const []const u8, total);
    var count: usize = 1;
    for (lists, values, 0..) |*list, value, s| {
        if (s >= width) {
            list.* = &.{value};
            continue;
        }
        var held: std.ArrayList([]const u8) = .empty;
        defer held.deinit(arena);
        var split = Layers.init(value);
        while (split.next()) |layer| try held.append(arena, layer);
        list.* = try held.toOwnedSlice(arena);
        count = @max(count, list.*.len);
    }

    var written: std.ArrayList([]const u8) = .empty;
    defer written.deinit(arena);
    for (0..count) |n| {
        var kept: std.ArrayList([]const u8) = .empty;
        defer kept.deinit(arena);
        for (0..total) |i| {
            const s = if (entry.order.len > 0) entry.order[i] else i;
            // A collapsing box pair is written as a unit, and `mask` is the
            // reason the flag exists: with the two agreeing it writes one
            // component where `background` writes both, and with the origin at
            // its initial it writes it anyway -- unless the clip holds a value
            // the origin could not take, which is why `mask: border-box
            // no-clip` answers just `no-clip`.
            if (entry.box_collapse and s == entry.boxes[1]) continue;
            if (entry.box_collapse and s == entry.boxes[0]) {
                const origin = layerAt(lists[entry.boxes[0]], entry, entry.boxes[0], n, count) orelse continue;
                const clip = layerAt(lists[entry.boxes[1]], entry, entry.boxes[1], n, count) orelse continue;
                const bare_origin = dropped(entry.omit[entry.boxes[0]], origin);
                const one = if (bare_origin) entry.fillers[entry.boxes[0]] else origin;
                const other = if (dropped(entry.omit[entry.boxes[1]], clip))
                    entry.fillers[entry.boxes[1]]
                else
                    clip;
                if (std.ascii.eqlIgnoreCase(one, other)) {
                    if (!bare_origin) try kept.append(arena, one);
                } else if (bare_origin and !accepts(entry.longhands[entry.boxes[0]], other)) {
                    try kept.append(arena, other);
                } else {
                    try kept.append(arena, one);
                    try kept.append(arena, other);
                }
                continue;
            }
            const held = layerAt(lists[s], entry, s, n, count) orelse continue;
            if (dropped(entry.omit[s], held)) continue;
            if (s == entry.size_slot) try kept.append(arena, "/");
            try kept.append(arena, held);
        }
        if (kept.items.len == 0) {
            try written.append(arena, entry.empty orelse "");
            continue;
        }
        try written.append(arena, try std.mem.join(arena, " ", kept.items));
    }
    return std.mem.join(arena, ", ", written.items);
}

/// What one slot holds in layer `n`: a shared slot only in the last layer, and
/// nothing at all where a longhand's list is shorter than the layer count --
/// measured, a `background-image` with two layers over a one-layer position
/// leaves the second layer's position unwritten rather than repeating it.
fn layerAt(
    list: []const []const u8,
    entry: Shorthand,
    slot: usize,
    n: usize,
    count: usize,
) ?[]const u8 {
    if (slot >= entry.layer_width) {
        return if (n == count - 1) list[0] else null;
    }
    return if (n < list.len) list[n] else null;
}

/// A value's layers: top-level commas separate, parentheses and quotes hold.
pub const Layers = struct {
    text: []const u8,
    index: usize = 0,

    pub fn init(text: []const u8) Layers {
        return .{ .text = std.mem.trim(u8, text, &std.ascii.whitespace) };
    }

    pub fn next(self: *Layers) ?[]const u8 {
        if (self.index > self.text.len) return null;
        const start = self.index;
        var depth: usize = 0;
        var quote: ?u8 = null;
        while (self.index < self.text.len) : (self.index += 1) {
            const c = self.text[self.index];
            if (quote) |q| {
                if (c == q) quote = null;
                continue;
            }
            switch (c) {
                '"', '\'' => quote = c,
                '(' => depth += 1,
                ')' => depth -|= 1,
                ',' => if (depth == 0) {
                    const out = self.text[start..self.index];
                    self.index += 1;
                    return std.mem.trim(u8, out, &std.ascii.whitespace);
                },
                else => {},
            }
        }
        const out = self.text[start..self.index];
        self.index += 1;
        return std.mem.trim(u8, out, &std.ascii.whitespace);
    }
};

// --- the grammar --------------------------------------------------------

/// The widest group any measured shorthand has, so the slots fit on the stack.
const max_group = 8;

fn slotOf(entry: Shorthand, index: usize) usize {
    return if (entry.blocked) index / entry.groups else index % entry.group;
}

/// The longhand standing for a component slot: the first of its block when the
/// repeats are blocked (`border`'s four widths), the slot itself otherwise.
fn representative(entry: Shorthand, slot: usize) usize {
    return if (entry.blocked) slot * entry.groups else slot;
}

/// Which slot a component goes to: the first one still empty that accepts it.
/// Position is not the test -- `1px solid red`, `solid red 1px` and
/// `red 1px solid` all land identically, measured.
fn place(entry: Shorthand, component: []const u8, slots: []const []const u8) ?usize {
    for (slots, 0..) |held, slot| {
        if (held.len > 0) continue;
        if (!accepts(entry.longhands[representative(entry, slot)], component)) continue;
        return slot;
    }
    return null;
}

fn accepts(longhand: []const u8, component: []const u8) bool {
    const classes = classify(component);
    if (classes.identifier) {
        if (chrome_keywords.keywords.get(longhand)) |known| {
            for (known) |keyword| {
                if (std.ascii.eqlIgnoreCase(keyword, component)) return true;
            }
        }
    }
    // An easing written as a function. The generator measured both
    // timing-function longhands as taking no value class at all -- the class
    // vocabulary has no name for an easing -- so `cubic-bezier()` matched
    // nothing below, `place` found it no slot, and the whole shorthand declined
    // and was kept as the author wrote it. That is why `animation: a 1s
    // cubic-bezier(...)` did not expand where `animation: a 1s linear` did.
    // Measured with tools/fingerprint/probes/expr-animation-serialize.js.
    if (isEasingFunction(component) and isTimingFunction(longhand)) {
        return true;
    }

    const taken = valueClasses(longhand);
    for (taken) |class| {
        if (switch (class) {
            .length => classes.length,
            .percent => classes.percent,
            .number => classes.number,
            .angle => classes.angle,
            .time => classes.time,
            .url => classes.url,
            .string => classes.string,
            .identifier => classes.identifier,
            .colour => classes.colour,
            .function => classes.function,
            .gradient => classes.gradient,
            .image => classes.image,
        }) return true;
    }
    return false;
}

// -- refusing a declaration --------------------------------------------------
//
// Everything above answers what a value *becomes*. This answers whether it
// becomes anything at all: Chrome throws a declaration it cannot parse away,
// where this engine's only other answer is to keep it whole. Measured over 525
// readings by tools/fingerprint/probes/probe-css17.js.
//
// The whole of it is conservative in one direction, deliberately. Keeping a
// declaration Chrome refused is the reading this engine already gave before any
// of this existed -- wrong, but wrong in a way pages survive. Refusing one
// Chrome kept is a new kind of wrong: the page loses a style it was written
// with. So every test here is a licence to refuse rather than a requirement to
// accept, and anything it cannot judge is kept.

/// Whether Chrome throws a *longhand* declaration away. Two independent tests,
/// measured: the value classes the property takes (`accepts`), and the range it
/// takes them in (`chrome_bounds`, which the classes cannot see -- `-10px` and
/// `10px` are both a `<length>` and `margin` takes one where `padding` does not).
pub fn refusesLonghand(name: []const u8, value: []const u8) bool {
    if (!judgeable(value)) return false;
    if (cssWide(std.mem.trim(u8, value, &std.ascii.whitespace)) != null) return false;

    // The grammar half is only asked of a property the generator measured a
    // value class for. A keyword-only longhand has an empty class list, so
    // `accepts` there is the keyword table alone, and a keyword missing from it
    // would read as a refusal rather than as the gap it is.
    const graded_name = gradedName(name);
    const classes = valueClasses(graded_name);
    const graded = classes.len > 0;

    var components = slashComponents(value);
    while (components.next()) |component| {
        if (outOfBounds(name, component)) return true;
        if (graded and !accepts(graded_name, component)) return true;
    }
    return false;
}

/// The name whose measured grammar answers for this one. Only the four logical
/// corner spellings need it: `border-radius` expands to the *physical* four, so
/// no shorthand has ever handed the generator a `border-start-start-radius` and
/// neither the class table nor the keyword table has heard of it. Measured
/// (probe-css16, probe-css17): a logical corner takes and refuses exactly what
/// the physical one does, which is what makes standing in for it honest.
/// The value classes a longhand takes, measured. An empty answer means "not
/// measured", which reads the same as "matches nothing" at both call sites.
///
/// `chrome_shorthands.value_classes` is generated by walking the longhands of
/// the shorthands the generator probes, so a longhand nothing expands to never
/// got measured and has no entry -- and no entry means `refusesLonghand` skips
/// its grammar check entirely. `color` is one of those: nothing expands to it,
/// so `color: FakeColor` was stored here where Chrome drops the declaration.
/// Kasada plants exactly that identifier at x-hyatt and reads the computed
/// value back (tools/fingerprint/results/b55-answers-lp.json), which makes the
/// gap a tell rather than a rounding error.
///
/// The same gap is what `src/browser/tests/css/arity_pool_ceiling.html` leaves
/// six declarations to. `clip-path`, `shape-outside`, `border-shape` and
/// `scroll-marker-group` are all longhands nothing expands to, so nothing
/// grades their components; the arity count used to refuse every two-component
/// value they were given, which hid the gap by also refusing the valid ones.
/// Now that the count is right, `clip-path: circle() nonsense` is kept. Closing
/// it means measuring value classes for the longhands no shorthand reaches --
/// the same remedy as the colours below, one property at a time.
///
/// Measured with tools/fingerprint/probes/expr-b55-color-classes.js on the
/// generator's own token battery, so the answer is in the same vocabulary:
/// `color` takes `#abc` and `rgb(1, 2, 3)` and refuses the other ten, which is
/// the pair the generator wrote for `background-color`.
///
/// Sixteen further colour longhands have the same gap -- `caret-color`,
/// `accent-color`, `fill`, `stroke`, `flood-color`, `stop-color`,
/// `-webkit-text-fill-color` and the logical border-colour spellings among
/// them. They are deliberately not here: grading a property whose keyword table
/// is short of one real keyword turns a valid declaration into a dropped one,
/// so each needs its own measurement rather than `color`'s answer copied
/// across. `color`'s keyword table is the whole colour list plus
/// `currentcolor`, which is what makes grading it safe.
///
/// The return type is deliberately not optional. Writing it `?[]const
/// table.Class` and answering `null` here crashes the Zig 0.16 backend with a
/// SIGSEGV in `build-exe`, reproducibly: adding the `?` fails the build and
/// taking it away builds clean, with nothing else changed.
const color_classes = [_]table.Class{ .colour, .function };

/// The same gap on the SVG side of the `<alpha-value>` family, and the same
/// remedy. `opacity` and `shape-image-threshold` were measured because the two
/// `-webkit-` aliases expand to them; nothing expands to `fill-opacity`,
/// `stroke-opacity`, `stop-opacity` or `flood-opacity`, so they were never
/// graded and `fill-opacity: 50px` was stored here -- and reported as a
/// computed `50px`, which is not a value any browser prints for an opacity.
///
/// Copied across rather than measured separately only because the measurement
/// says they are the same property twice over: on the generator's own twelve
/// token battery plus eighteen shapes an `<alpha-value>` can take
/// (scratch/b98/expr-b98-alpha-classes.js, Chrome 151), all six answer
/// identically on all thirty -- `1%` `2` `0.5` `-0.1` `1.5` `50%` `5e-1`
/// `calc(...)` `var()` and the CSS-wide keywords kept, everything else dropped,
/// with no exception in either direction. Their keyword tables are empty too,
/// which is what makes grading them safe: there is no real keyword left for the
/// grammar check to mistake for a refusal.
const alpha_classes = [_]table.Class{ .percent, .number };

fn valueClasses(longhand: []const u8) []const table.Class {
    if (table.value_classes.get(longhand)) |classes| return classes;
    if (std.mem.eql(u8, longhand, "color")) return &color_classes;
    if (isSvgAlphaProperty(longhand)) return &alpha_classes;
    return &.{};
}

fn isSvgAlphaProperty(name: []const u8) bool {
    const names = [_][]const u8{
        "fill-opacity", "stroke-opacity", "stop-opacity", "flood-opacity",
    };
    for (names) |candidate| {
        if (std.mem.eql(u8, name, candidate)) return true;
    }
    return false;
}

fn gradedName(name: []const u8) []const u8 {
    const logical = std.StaticStringMap([]const u8).initComptime(.{
        .{ "border-start-start-radius", "border-top-left-radius" },
        .{ "border-start-end-radius", "border-top-right-radius" },
        .{ "border-end-start-radius", "border-bottom-left-radius" },
        .{ "border-end-end-radius", "border-bottom-right-radius" },
    });
    return logical.get(name) orelse name;
}

/// The value's components with the `/` among them rather than stopping at it.
/// Every model above stops, because a `/` is a shorthand's punctuation and none
/// of them has a use for one; a refusal test wants the opposite, since a `/` no
/// class accepts is exactly the sort of thing Chrome throws the declaration
/// away for -- `border-top-left-radius: 10px / 20px`, measured.
pub fn slashComponents(value: []const u8) Components {
    var components = Components.init(value);
    components.slash = true;
    return components;
}

/// Whether a shorthand `expand` declined is Chrome's refusal rather than this
/// engine's retreat. `expand` answers null for both and the difference is the
/// whole point: a `.layers` or `.components` model is licenced to decline a row
/// Chrome accepts, so only the two kinds whose decline *is* a grammar failure
/// are read as one -- a box that was handed five components, and a corner list
/// whose slashes do not work out.
pub fn refusesDeclined(entry: Shorthand, value: []const u8) bool {
    switch (entry.kind) {
        .box4, .box2, .corners => {},
        else => return false,
    }
    if (cssWide(std.mem.trim(u8, value, &std.ascii.whitespace)) != null) return false;
    return judgeable(value);
}

/// Whether the value fails the CSS `<position>` grammar of a property that
/// takes one, in which case Chrome drops the declaration entirely --
/// `getPropertyValue` answers the empty string and the computed value is the
/// initial one.
///
/// This is a grammar and not a component check, which is why `refusesLonghand`
/// above cannot do it: every token of `background-position: top 30%` is a
/// component the property takes, and the declaration is invalid all the same
/// because `top` names the vertical axis and `30%` then has nowhere to go. Of
/// 230 readings over 46 values and these five properties, 99 disagreed with
/// Chrome and every one of them was this -- Chrome dropping where this engine
/// kept (scratch/b91/expr-position-grammar.js).
///
/// The five do not share one grammar. Measured, not read off a spec:
///
///   background-position   `<bg-position>`, the only one that still takes the
///                         legacy three-value form (`left 10px top`).
///   mask-position         plain `<position>`: one, two or four values, the
///   object-position       three-value form refused. css-values-3 moved that
///   perspective-origin    form out of `<position>` and Chrome followed; these
///                         three refuse byte for byte alike.
///   transform-origin      `<position>{1,2}` then an optional `<length>` z
///                         offset -- so `left top 10px` and `10px 20px 30px`
///                         are fine and no four-value form is.
///
/// `background-position-x` / `-y` are deliberately absent: their grammar is a
/// comma list of edge-relative offsets, nobody has measured it, and a
/// `<position>` check over it would refuse what Chrome takes. The shorthand is
/// judged here before it expands into them.
pub fn refusesPosition(name: []const u8, value: []const u8) bool {
    const grammar = positionGrammar(name) orelse return false;
    const trimmed = std.mem.trim(u8, value, &std.ascii.whitespace);
    if (trimmed.len == 0) return false;
    if (cssWide(trimmed) != null) return false;
    if (!judgeable(trimmed)) return false;

    var tokens: [8][]const u8 = undefined;
    var count: usize = 0;
    var walk = std.mem.tokenizeAny(u8, trimmed, &std.ascii.whitespace);
    while (walk.next()) |token| {
        // Longer than any position, so it cannot be one. Counting past the
        // buffer rather than refusing here keeps the arity check in one place.
        if (count == tokens.len) return true;
        tokens[count] = token;
        count += 1;
    }

    if (grammar == .position_and_z) {
        // The position half is one or two values -- not the four-value form the
        // others take -- and the z offset is a plain <length> after it. Which
        // is why `left top 10px` is fine here and refused everywhere else,
        // while `left 10px top 20px` is the other way round.
        if (count <= 2) return !isPosition(tokens[0..count], .position);
        if (count == 3) {
            return !(isLength(tokens[2]) and isPosition(tokens[0..2], .position));
        }
        return true;
    }
    return !isPosition(tokens[0..count], grammar);
}

/// One axis of a `<position>`, in the shape both of Chrome's serializations are
/// written from: the edge an offset is measured from, and the offset itself.
///
/// Either half may be absent, and which are present is the whole of what decides
/// how many values the specified value prints -- `left` is a bare edge, `30%` a
/// bare offset, and `left 10px` in the three- and four-value forms is both. That
/// is why one and two values both come back as two while four come back as four:
/// nothing counts the author's tokens, each axis just prints what it has.
pub const PositionAxis = struct {
    edge: ?Edge = null,
    /// The offset token exactly as the author wrote it; converting it needs
    /// units and an element, neither of which belongs in this file.
    offset: ?[]const u8 = null,

    /// Named for the axis's own start rather than for a side, because the same
    /// three answer both axes: `left` and `top` are `.start`, `right` and
    /// `bottom` are `.end`.
    pub const Edge = enum { start, center, end };

    /// The keyword this edge is spelled with on the axis it sits on.
    pub fn keyword(self: PositionAxis, axis: enum { horizontal, vertical }) ?[]const u8 {
        return switch (self.edge orelse return null) {
            .start => if (axis == .horizontal) "left" else "top",
            .center => "center",
            .end => if (axis == .horizontal) "right" else "bottom",
        };
    }
};

/// A `<position>` taken apart into its two axes, whatever order and arity the
/// author wrote it in. `z` is transform-origin's third component, which is a
/// plain length on no axis at all.
pub const Position = struct {
    horizontal: PositionAxis = .{},
    vertical: PositionAxis = .{},
    z: ?[]const u8 = null,
};

/// The value taken apart into its two axes, or null when this file cannot model
/// it -- which is NOT the same question as `refusesPosition`, and deliberately
/// so. That function decides what Chrome *accepts*, and it is measured against
/// 230 readings; this one decides what can be re-serialised, and answering null
/// leaves the caller printing what it printed before. Keeping them apart means a
/// gap here can only ever cost fidelity, never turn a declaration Chrome takes
/// into one this engine drops.
///
/// So the shapes below are the ones both agree on. A `center` carrying an offset
/// is the one shape `refusesPosition` allows and this refuses: `center` is the
/// middle of the box and has no edge to measure from, and no measurement says
/// what Chrome prints for it.
pub fn parsePosition(name: []const u8, value: []const u8) ?Position {
    const grammar = positionGrammar(name) orelse return null;
    const trimmed = std.mem.trim(u8, value, &std.ascii.whitespace);
    if (trimmed.len == 0) return null;
    if (cssWide(trimmed) != null) return null;
    if (!judgeable(trimmed)) return null;

    var tokens: [8][]const u8 = undefined;
    var count: usize = 0;
    var walk = std.mem.tokenizeAny(u8, trimmed, &std.ascii.whitespace);
    while (walk.next()) |token| {
        if (count == tokens.len) return null;
        tokens[count] = token;
        count += 1;
    }

    if (grammar == .position_and_z) {
        // The z offset is a plain length after a one- or two-value position, so
        // `left top 10px` is a position and a z here where the same three tokens
        // are an edge-relative position on `background-position`.
        if (count <= 2) return positionAxes(tokens[0..count], grammar, null);
        if (count == 3 and isLength(tokens[2])) {
            return positionAxes(tokens[0..2], grammar, tokens[2]);
        }
        return null;
    }
    return positionAxes(tokens[0..count], grammar, null);
}

fn positionAxes(tokens: []const []const u8, grammar: PositionGrammar, z: ?[]const u8) ?Position {
    switch (tokens.len) {
        1 => {
            if (edgeToken(tokens[0])) |edge| {
                return placeAxes(edge, null, .{ .axis = .either, .edge = .center }, null, z);
            }
            if (!isLengthPercentage(tokens[0])) return null;
            // A lone offset is horizontal, and the axis it left out is centred.
            return .{
                .horizontal = .{ .offset = tokens[0] },
                .vertical = .{ .edge = .center },
                .z = z,
            };
        },
        2 => {
            const lead = edgeToken(tokens[0]);
            const follow = edgeToken(tokens[1]);
            if (lead != null and follow != null) {
                // Two keywords are the `&&` half of the grammar: each takes the
                // axis it names whichever slot it sits in, so `bottom left` is
                // `left bottom` and `center left` is `left center`.
                return placeAxes(lead.?, null, follow.?, null, z);
            }
            // With an offset in play the form is slot-ordered -- horizontal
            // first, vertical second -- and an offset takes the axis of its slot
            // rather than of a keyword.
            if (lead == null) {
                if (!isLengthPercentage(tokens[0])) return null;
                const vertical: PositionAxis = if (follow) |edge| blk: {
                    if (edge.axis == .horizontal) return null;
                    break :blk .{ .edge = edge.edge };
                } else if (isLengthPercentage(tokens[1]))
                    .{ .offset = tokens[1] }
                else
                    return null;
                return .{ .horizontal = .{ .offset = tokens[0] }, .vertical = vertical, .z = z };
            }
            if (!isLengthPercentage(tokens[1])) return null;
            if (lead.?.axis == .vertical) return null;
            return .{
                .horizontal = .{ .edge = lead.?.edge },
                .vertical = .{ .offset = tokens[1] },
                .z = z,
            };
        },
        // `left 10px top` -- one edge carrying an offset and one bare. The
        // offset belongs to the edge in front of it, so it is in slot 1 or 2 and
        // the edges are whatever is left.
        3 => {
            if (grammar != .bg_position) return null;
            if (isLengthPercentage(tokens[1])) {
                const first = edgeToken(tokens[0]) orelse return null;
                const second = edgeToken(tokens[2]) orelse return null;
                return placeAxes(first, tokens[1], second, null, z);
            }
            if (isLengthPercentage(tokens[2])) {
                const first = edgeToken(tokens[0]) orelse return null;
                const second = edgeToken(tokens[1]) orelse return null;
                return placeAxes(first, null, second, tokens[2], z);
            }
            return null;
        },
        // `left 10px top 20px` -- both edges carry an offset.
        4 => {
            if (!isLengthPercentage(tokens[1]) or !isLengthPercentage(tokens[3])) return null;
            const first = edgeToken(tokens[0]) orelse return null;
            const second = edgeToken(tokens[2]) orelse return null;
            return placeAxes(first, tokens[1], second, tokens[3], z);
        },
        else => return null,
    }
}

/// Two edges, each with the offset it carries, put on the axes they name.
/// `center` names neither, so it takes whichever axis the other one leaves --
/// and when both are `center` the two halves are the same answer anyway.
fn placeAxes(
    first: TokenEdge,
    first_offset: ?[]const u8,
    second: TokenEdge,
    second_offset: ?[]const u8,
    z: ?[]const u8,
) ?Position {
    // `center` is the middle of the box, not an edge to measure from. The
    // grammar check lets one through in the three-value form; nothing has
    // measured what Chrome prints for it, so it is not modelled here.
    if (first.axis == .either and first_offset != null) return null;
    if (second.axis == .either and second_offset != null) return null;

    const first_axis: PositionAxis = .{ .edge = first.edge, .offset = first_offset };
    const second_axis: PositionAxis = .{ .edge = second.edge, .offset = second_offset };

    if (first.axis == .horizontal) {
        if (second.axis == .horizontal) return null;
        return .{ .horizontal = first_axis, .vertical = second_axis, .z = z };
    }
    if (first.axis == .vertical) {
        if (second.axis == .vertical) return null;
        return .{ .horizontal = second_axis, .vertical = first_axis, .z = z };
    }
    // The first is `center`, so the second decides.
    return switch (second.axis) {
        .horizontal => .{ .horizontal = second_axis, .vertical = first_axis, .z = z },
        else => .{ .horizontal = first_axis, .vertical = second_axis, .z = z },
    };
}

/// Which axis a per-axis position longhand holds, or null for a property that
/// is not one.
///
/// Both shorthands that take a `<position>` and expand are stored this way, and
/// the two pairs are spelled differently only by history: `background-position`
/// splits into `background-position-x` and `-y`, `mask-position` into the
/// `-webkit-` prefixed pair. A value that reaches either pair has already been
/// split, so what is left on each is one axis.
pub const WhichAxis = enum { horizontal, vertical };

pub fn positionAxisProperty(name: []const u8) ?WhichAxis {
    const AXES = std.StaticStringMap(WhichAxis).initComptime(.{
        .{ "background-position-x", .horizontal },
        .{ "background-position-y", .vertical },
        .{ "-webkit-mask-position-x", .horizontal },
        .{ "-webkit-mask-position-y", .vertical },
    });
    return AXES.get(name);
}

/// One axis on its own, which is what `background-position-x` and its three
/// siblings hold: an edge, an offset, or an edge and an offset. Chrome stores a
/// position shorthand's two halves in exactly this shape and computes each half
/// by itself -- `background-position: right 10px bottom 20px` puts `right 10px`
/// in the x longhand, which computes to `calc(100% - 10px)` on its own and joins
/// back into the shorthand's answer. Measured with
/// scratch/b92/expr-position-longhand.js.
///
/// Null for the comma-separated multi-layer form these longhands also take.
/// Nobody has measured that, and this file does not model a layer list.
pub fn parsePositionAxis(name: []const u8, value: []const u8) ?PositionAxis {
    const vertical = (positionAxisProperty(name) orelse return null) == .vertical;

    const trimmed = std.mem.trim(u8, value, &std.ascii.whitespace);
    if (trimmed.len == 0) return null;
    if (cssWide(trimmed) != null) return null;
    if (!judgeable(trimmed)) return null;

    var tokens: [2][]const u8 = undefined;
    var count: usize = 0;
    var walk = std.mem.tokenizeAny(u8, trimmed, &std.ascii.whitespace);
    while (walk.next()) |token| {
        if (count == tokens.len) return null;
        tokens[count] = token;
        count += 1;
    }

    // An edge on this longhand has to name this longhand's own axis: `left` is
    // not a `background-position-y`.
    const wanted: Axis = if (vertical) .vertical else .horizontal;
    if (count == 1) {
        if (edgeToken(tokens[0])) |edge| {
            if (edge.axis != wanted and edge.axis != .either) return null;
            return .{ .edge = edge.edge };
        }
        if (!isLengthPercentage(tokens[0])) return null;
        return .{ .offset = tokens[0] };
    }
    if (count != 2) return null;
    const edge = edgeToken(tokens[0]) orelse return null;
    // `center` takes no offset here for the same reason it takes none above.
    if (edge.axis != wanted) return null;
    if (!isLengthPercentage(tokens[1])) return null;
    return .{ .edge = edge.edge, .offset = tokens[1] };
}

const TokenEdge = struct { axis: Axis, edge: PositionAxis.Edge };

fn edgeToken(token: []const u8) ?TokenEdge {
    if (std.ascii.eqlIgnoreCase(token, "left")) return .{ .axis = .horizontal, .edge = .start };
    if (std.ascii.eqlIgnoreCase(token, "right")) return .{ .axis = .horizontal, .edge = .end };
    if (std.ascii.eqlIgnoreCase(token, "top")) return .{ .axis = .vertical, .edge = .start };
    if (std.ascii.eqlIgnoreCase(token, "bottom")) return .{ .axis = .vertical, .edge = .end };
    if (std.ascii.eqlIgnoreCase(token, "center")) return .{ .axis = .either, .edge = .center };
    return null;
}

const PositionGrammar = enum {
    /// `<position>`: one, two or four values.
    position,
    /// `<bg-position>`: the above plus the legacy three-value form.
    bg_position,
    /// `<position>{1,2}` then an optional `<length>`.
    position_and_z,
};

fn positionGrammar(name: []const u8) ?PositionGrammar {
    const GRAMMARS = std.StaticStringMap(PositionGrammar).initComptime(.{
        .{ "background-position", .bg_position },
        .{ "mask-position", .position },
        .{ "object-position", .position },
        .{ "perspective-origin", .position },
        .{ "transform-origin", .position_and_z },
    });
    return GRAMMARS.get(name);
}

const Axis = enum { horizontal, vertical, either, offset, none };

/// Which half of a position a token can be, on its own.
fn positionToken(token: []const u8) Axis {
    if (std.ascii.eqlIgnoreCase(token, "left") or std.ascii.eqlIgnoreCase(token, "right")) {
        return .horizontal;
    }
    if (std.ascii.eqlIgnoreCase(token, "top") or std.ascii.eqlIgnoreCase(token, "bottom")) {
        return .vertical;
    }
    if (std.ascii.eqlIgnoreCase(token, "center")) return .either;
    if (isLengthPercentage(token)) return .offset;
    return .none;
}

fn isLengthPercentage(token: []const u8) bool {
    const classes = classify(token);
    return (classes.length or classes.percent) and !unknownUnit(token);
}

fn isLength(token: []const u8) bool {
    const classes = classify(token);
    return classes.length and !classes.percent and !unknownUnit(token);
}

fn isPosition(tokens: []const []const u8, grammar: PositionGrammar) bool {
    switch (tokens.len) {
        // Any single keyword or offset; the other axis is implied `center`.
        1 => return positionToken(tokens[0]) != .none,
        2 => {
            const first = positionToken(tokens[0]);
            const second = positionToken(tokens[1]);
            if (first == .none or second == .none) return false;
            // `center left` is legal and `30% left` is not, so this is not
            // "each token fits an axis" -- it is the `&&` half of the grammar,
            // where a keyword may lead only if the other half is a keyword too.
            // An offset takes its axis from its slot, so it can only ever be
            // horizontal first and vertical second.
            if (first == .offset and (second == .horizontal or second == .vertical)) {
                return second == .vertical;
            }
            if (second == .offset) return first != .vertical;
            return !sameAxis(first, second);
        },
        // `left 10px top` -- one edge with an offset and one bare. Only
        // `<bg-position>` still has it.
        3 => {
            if (grammar != .bg_position) return false;
            // The offset belongs to the edge before it, so it is in slot 1 or
            // slot 2 and the two edges are whatever is left.
            if (positionToken(tokens[1]) == .offset) {
                return edgePair(tokens[0], tokens[2]);
            }
            if (positionToken(tokens[2]) == .offset) {
                return edgePair(tokens[0], tokens[1]);
            }
            return false;
        },
        // `left 10px top 20px` -- both edges carry an offset, so both must be
        // keywords and `center` cannot be one: it takes no offset.
        4 => {
            if (positionToken(tokens[1]) != .offset or positionToken(tokens[3]) != .offset) {
                return false;
            }
            const first = positionToken(tokens[0]);
            const second = positionToken(tokens[2]);
            if (first == .either or second == .either) return false;
            return (first == .horizontal or first == .vertical) and !sameAxis(first, second);
        },
        else => return false,
    }
}

/// Two edges naming different axes, `center` standing in for whichever is left.
/// An offset cannot be one: in the three- and four-value forms an offset always
/// belongs to the edge in front of it.
fn edgePair(a: []const u8, b: []const u8) bool {
    const first = positionToken(a);
    const second = positionToken(b);
    if (first == .none or second == .none or first == .offset or second == .offset) {
        return false;
    }
    return !sameAxis(first, second);
}

fn sameAxis(a: Axis, b: Axis) bool {
    if (a == .either or b == .either) return false;
    return a == b;
}

/// Whether this engine can say anything about the value at all. It cannot when
/// a component is a function whose name `classify` does not know -- `calc()` is
/// the live one, because Chrome evaluates it and this engine substitutes it, so
/// neither the class nor the sign of what it holds is visible from here. Nor
/// when the value carries a comma: a comma-separated list is a grammar nothing
/// in this file models, and splitting it on whitespace would judge `Arial,` as
/// a malformed identifier.
fn judgeable(value: []const u8) bool {
    if (std.mem.indexOfScalar(u8, value, ',') != null) return false;
    // A comment. Chrome takes it out and keeps the declaration -- `margin: 10px
    // /* c */ 20px` is `10px 20px` -- and nothing here removes one, so the
    // components would come back as punctuation no class accepts.
    if (std.mem.indexOf(u8, value, "/*") != null) return false;
    var components = slashComponents(value);
    while (components.next()) |component| {
        if (component.len == 0 or component[component.len - 1] != ')') continue;
        const open = std.mem.indexOfScalar(u8, component, '(') orelse continue;
        if (!hasClass(functionClass(component[0..open]))) return false;
    }
    return components.exhausted();
}

/// Whether the component is outside the range the property takes them in.
fn outOfBounds(property: []const u8, component: []const u8) bool {
    if (unknownUnit(component)) return true;
    const classes = classify(component);
    if (classes.percent and chrome_bounds.no_percent.has(property)) return true;
    if (classes.number and outsideNumberRange(property, component)) return true;
    if (!classes.length and !classes.percent and !classes.number and
        !classes.angle and !classes.time) return false;
    if (!negative(component)) return false;
    return chrome_bounds.no_negative.has(property);
}

/// Whether the component is a number carrying a run of letters no unit spells.
/// `classify` reads any of them as a unit and answers `<length>`, which is the
/// right guess for placing a component and the wrong one for judging it: there
/// is no property `10foo` belongs to, so this is asked of every property rather
/// than of the ones with a measured class list.
///
/// The lookup folds case, because `10PX` is `10px`. A spelling longer than
/// anything in the table is answered without folding it anywhere.
fn unknownUnit(component: []const u8) bool {
    const digits = numberEnd(component);
    if (digits == 0) return false;
    const unit = component[digits..];
    if (unit.len == 0) return false;
    // A `%` is not a unit spelling and has its own class; anything else with a
    // non-letter in it classified as nothing before this existed and still does.
    for (unit) |c| {
        if (!std.ascii.isAlphabetic(c)) return false;
    }
    if (unit.len > chrome_units.longest) return true;
    var folded: [chrome_units.longest]u8 = undefined;
    for (unit, 0..) |c, i| folded[i] = std.ascii.toLower(c);
    return !chrome_units.units.has(folded[0..unit.len]);
}

/// Whether a bare number is one this property does not take: outside a bound
/// that was measured and bisected, a fraction where only whole numbers go, or a
/// bare number at all where the property wants a unit on one. That last test
/// belongs here rather than with the value classes because a unitless zero is a
/// `<length>` as much as it is a number, so the classes wave it through --
/// `rotate: 0` and `overflow-clip-margin: 0` are refused where `0deg` and `0px`
/// are kept, measured.
///
/// A number this cannot read is not a number this refuses. The bounds are a
/// licence to throw a declaration away and nothing here is allowed to guess.
fn outsideNumberRange(property: []const u8, component: []const u8) bool {
    if (chrome_bounds.needs_unit.has(property)) return true;
    const range = chrome_bounds.number_range.get(property) orelse return false;
    const value = std.fmt.parseFloat(f64, component) catch return false;
    if (range.min) |min| if (value < min) return true;
    if (range.max) |max| if (value > max) return true;
    return range.integer and @floor(value) != value;
}

/// A leading minus is not a negative number. `padding: -0px` is accepted
/// everywhere `0px` is and reads back with the sign dropped, measured -- and so
/// a property name that happens to start with one (`-webkit-fill-available`) is
/// not a number at all, which `numberEnd` answering 0 already says.
fn negative(component: []const u8) bool {
    if (component.len == 0 or component[0] != '-') return false;
    return !isZero(component[0..numberEnd(component)]);
}

fn hasClass(classes: Classes) bool {
    return classes.length or classes.percent or classes.number or classes.angle or
        classes.time or classes.url or classes.string or classes.identifier or
        classes.colour or classes.function or classes.gradient or classes.image;
}

const Classes = packed struct {
    length: bool = false,
    percent: bool = false,
    number: bool = false,
    angle: bool = false,
    time: bool = false,
    url: bool = false,
    string: bool = false,
    identifier: bool = false,
    colour: bool = false,
    function: bool = false,
    gradient: bool = false,
    image: bool = false,
};

/// A component's value classes, by shape alone -- the same test the generator
/// simulated before writing any of these tables down. A token can be in two:
/// a unitless zero is a `<length>` as well as a `<number>`, which is why
/// `border-top: 0` reaches the width.
fn classify(component: []const u8) Classes {
    if (component.len == 0) return .{};
    if (component[0] == '"' or component[0] == '\'') return .{ .string = true };
    if (component[0] == '#') {
        for (component[1..]) |c| {
            if (!std.ascii.isHex(c)) return .{};
        }
        return .{ .colour = true };
    }
    if (component[component.len - 1] == ')') {
        const open = std.mem.indexOfScalar(u8, component, '(') orelse return .{};
        return functionClass(component[0..open]);
    }
    const digits = numberEnd(component);
    if (digits == 0) {
        for (component, 0..) |c, i| {
            const ok = std.ascii.isAlphabetic(c) or c == '-' or c == '_' or
                (i > 0 and std.ascii.isDigit(c));
            if (!ok) return .{};
        }
        return .{ .identifier = true };
    }
    const unit = component[digits..];
    if (unit.len == 0) {
        return if (isZero(component)) .{ .length = true, .number = true } else .{ .number = true };
    }
    if (std.mem.eql(u8, unit, "%")) return .{ .percent = true };
    for ([_][]const u8{ "deg", "grad", "rad", "turn" }) |angle| {
        if (std.ascii.eqlIgnoreCase(unit, angle)) return .{ .angle = true };
    }
    for ([_][]const u8{ "s", "ms" }) |time| {
        if (std.ascii.eqlIgnoreCase(unit, time)) return .{ .time = true };
    }
    for (unit) |c| {
        if (!std.ascii.isAlphabetic(c)) return .{};
    }
    return .{ .length = true };
}

/// A function's class comes from its name rather than from the fact that it is
/// a function: `background-image` takes `linear-gradient()` and not `rgb()`, and
/// `background-color` the other way round, so a single `function` class puts a
/// gradient in the colour. A name this does not know has no class at all, and a
/// value carrying one is declined rather than guessed at.
fn functionClass(name: []const u8) Classes {
    if (std.ascii.eqlIgnoreCase(name, "url")) return .{ .url = true };
    if (std.ascii.endsWithIgnoreCase(name, "-gradient")) return .{ .gradient = true };
    if (std.ascii.eqlIgnoreCase(name, "image-set") or
        std.ascii.eqlIgnoreCase(name, "-webkit-image-set"))
    {
        return .{ .image = true };
    }
    for ([_][]const u8{
        "rgb",       "rgba",       "hsl",   "hsla",  "hwb",
        "lab",       "lch",        "oklab", "oklch", "color",
        "color-mix", "light-dark",
    }) |known| {
        if (std.ascii.eqlIgnoreCase(name, known)) return .{ .function = true };
    }
    return .{};
}

/// The two longhands an easing lands in. Both were measured with an empty value
/// class list, so `accepts` has to name them rather than read them off a table.
fn isTimingFunction(longhand: []const u8) bool {
    return std.mem.eql(u8, longhand, "animation-timing-function") or
        std.mem.eql(u8, longhand, "transition-timing-function");
}

/// Whether the component is an `<easing-function>` written as a call. The three
/// names are the whole of the grammar; a bare `ease` or `linear` is an
/// identifier and reaches the keyword table instead.
fn isEasingFunction(component: []const u8) bool {
    if (component.len == 0 or component[component.len - 1] != ')') return false;
    const open = std.mem.indexOfScalar(u8, component, '(') orelse return false;
    const name = component[0..open];
    for ([_][]const u8{ "cubic-bezier", "steps", "linear" }) |known| {
        if (std.ascii.eqlIgnoreCase(name, known)) return true;
    }
    return false;
}

/// How much of the component is a number, 0 when it does not start with one.
fn numberEnd(component: []const u8) usize {
    var i: usize = 0;
    if (i < component.len and (component[i] == '+' or component[i] == '-')) i += 1;
    const start = i;
    while (i < component.len and std.ascii.isDigit(component[i])) i += 1;
    if (i < component.len and component[i] == '.') {
        i += 1;
        while (i < component.len and std.ascii.isDigit(component[i])) i += 1;
    }
    if (i == start) return 0;
    // An exponent. Chrome takes one and prints the result -- `margin: 1E1px` is
    // `10px` -- and without this the `E1px` reads as a unit with a digit in it,
    // so the component classifies as nothing and a refusal test would throw the
    // declaration away.
    if (i < component.len and (component[i] == 'e' or component[i] == 'E')) {
        var exp = i + 1;
        if (exp < component.len and (component[exp] == '+' or component[exp] == '-')) exp += 1;
        const digits = exp;
        while (exp < component.len and std.ascii.isDigit(component[exp])) exp += 1;
        if (exp > digits) i = exp;
    }
    return i;
}

fn isZero(component: []const u8) bool {
    for (component) |c| {
        if (c != '0' and c != '.' and c != '+' and c != '-') return false;
    }
    return true;
}

fn cssWide(value: []const u8) ?[]const u8 {
    for (chrome_keywords.css_wide) |keyword| {
        if (std.ascii.eqlIgnoreCase(keyword, value)) return keyword;
    }
    return null;
}

fn translated(entry: Shorthand, value: []const u8) []const u8 {
    for (entry.translate) |pair| {
        if (std.ascii.eqlIgnoreCase(pair[0], value)) return pair[1];
    }
    return value;
}

fn preset(entry: Shorthand, value: []const u8) ?@TypeOf(entry.presets[0]) {
    for (entry.presets) |row| {
        if (std.ascii.eqlIgnoreCase(row[0], value)) return row;
    }
    return null;
}

fn dropped(omit: []const []const u8, value: []const u8) bool {
    for (omit) |candidate| {
        if (std.ascii.eqlIgnoreCase(candidate, value)) return true;
    }
    return false;
}

/// The 1/2/3/4-value box rule: top, right, bottom, left -- or start and end for
/// the two-longhand ones.
fn boxRule(written: []const []const u8, width: usize) ?[4][]const u8 {
    if (written.len == 0 or written.len > width) return null;
    var out: [4][]const u8 = .{ "", "", "", "" };
    if (width == 2) {
        out[0] = written[0];
        out[1] = if (written.len == 1) written[0] else written[1];
        return out;
    }
    out[0] = written[0];
    out[1] = if (written.len > 1) written[1] else written[0];
    out[2] = if (written.len > 2) written[2] else written[0];
    out[3] = if (written.len > 3) written[3] else out[1];
    return out;
}

/// The shortest form the box rule writes back: `1px 1px 1px 1px` is `1px`, and
/// `1px 2px 3px 2px` is `1px 2px 3px`.
fn boxForm(values: []const []const u8) []const []const u8 {
    const eq = std.ascii.eqlIgnoreCase;
    if (values.len == 2) return if (eq(values[0], values[1])) values[0..1] else values;
    if (!eq(values[1], values[3])) return values;
    if (!eq(values[0], values[2])) return values[0..3];
    return if (eq(values[0], values[1])) values[0..1] else values[0..2];
}

/// A value's top-level components: whitespace separates, a parenthesised or
/// quoted run stays whole, and a `/` is a component of its own -- which is how
/// a value carrying one is rejected rather than mis-split.
pub const Components = struct {
    text: []const u8,
    index: usize = 0,
    stopped: bool = false,
    /// Whether a `/` comes back as a component of its own. The flat models have
    /// no use for one, so they stop there instead and their shorthand keeps the
    /// value whole.
    slash: bool = false,

    pub fn init(text: []const u8) Components {
        return .{ .text = std.mem.trim(u8, text, &std.ascii.whitespace) };
    }

    pub fn next(self: *Components) ?[]const u8 {
        while (self.index < self.text.len and std.ascii.isWhitespace(self.text[self.index])) {
            self.index += 1;
        }
        if (self.index >= self.text.len) return null;
        const start = self.index;
        if (self.text[start] == '/') {
            if (!self.slash) {
                self.stopped = true;
                return null;
            }
            self.index += 1;
            return self.text[start..self.index];
        }
        var depth: usize = 0;
        var quote: ?u8 = null;
        while (self.index < self.text.len) : (self.index += 1) {
            const c = self.text[self.index];
            if (quote) |q| {
                if (c == q) quote = null;
                continue;
            }
            switch (c) {
                '"', '\'' => quote = c,
                '(' => depth += 1,
                ')' => depth -|= 1,
                '/' => if (depth == 0) break,
                else => if (depth == 0 and std.ascii.isWhitespace(c)) break,
            }
        }
        return self.text[start..self.index];
    }

    /// Whether the whole value was consumed, rather than abandoned at a `/`.
    pub fn exhausted(self: *Components) bool {
        if (self.stopped) return false;
        while (self.index < self.text.len) : (self.index += 1) {
            if (!std.ascii.isWhitespace(self.text[self.index])) return false;
        }
        return true;
    }
};

// ---------------------------------------------------------------------------
// Three grammars the generated table left `.unmodelled`
// ---------------------------------------------------------------------------
//
// `columns`, `list-style` and `grid-area` are marked `.unmodelled` because the
// generator could not reproduce every probe reading from the table's rules
// alone. Kept whole, they cost the four, three and four longhands they name:
// an author writing `columns: 3 100px` left `column-count` reading `auto`
// where Chrome reads `3` (measured, scratch/b93/expr-shorthand-cases.js).
//
// Cloudflare's widget encodes `JSON.stringify(getComputedStyle(el))` whole, so
// each of these travels in the payload of any page whose CSS uses the
// shorthand.
//
// Two of the three ARE the `.components` rule once their fillers are known --
// which is all the generator was missing -- so they run on the same machinery
// via a synthetic entry rather than a parser of their own. `grid-area` is not:
// its components are separated by `/` and an omitted one copies an earlier one
// rather than taking a filler.

const columns_longhands = [_][]const u8{ "column-width", "column-count", "column-height", "column-wrap" };
const columns_fillers = [_][]const u8{ "auto", "auto", "auto", "auto" };
const list_style_longhands = [_][]const u8{ "list-style-position", "list-style-image", "list-style-type" };
const list_style_fillers = [_][]const u8{ "outside", "none", "disc" };
const grid_area_longhands = [_][]const u8{ "grid-row-start", "grid-column-start", "grid-row-end", "grid-column-end" };

/// Told from its shape, the way `isFont` and `isBorderImage` are: by the time
/// `join` sees an entry there is no name left to match on.
fn isColumns(entry: Shorthand) bool {
    return entry.kind == .unmodelled and
        entry.longhands.len == 4 and
        std.mem.eql(u8, entry.longhands[0], "column-width") and
        std.mem.eql(u8, entry.longhands[1], "column-count");
}

fn isListStyle(entry: Shorthand) bool {
    return entry.kind == .unmodelled and
        entry.longhands.len == 3 and
        std.mem.eql(u8, entry.longhands[0], "list-style-position");
}

fn isGridArea(entry: Shorthand) bool {
    return entry.kind == .unmodelled and
        entry.longhands.len == 4 and
        std.mem.eql(u8, entry.longhands[0], "grid-row-start");
}

/// `grid-row` and `grid-column`: `grid-area`'s grammar with two slots instead
/// of four, and the same rule for the omitted one.
fn isGridLinePair(entry: Shorthand) bool {
    return entry.kind == .unmodelled and
        entry.longhands.len == 2 and
        (std.mem.eql(u8, entry.longhands[0], "grid-row-start") or
            std.mem.eql(u8, entry.longhands[0], "grid-column-start"));
}

/// What Chrome stores for one of the three, or null for anything else --
/// including a CSS-wide keyword, which these still keep whole, and a value the
/// grammar refuses, which keeps the pre-existing behaviour of storing it whole.
///
/// Sits beside the table lookup rather than inside `expand` for the same reason
/// `fontExpansion` does: `lookup` declines an unmodelled entry before `expand`
/// is ever reached.
pub fn grammarExpansion(arena: Allocator, name: []const u8, value: []const u8) !?Expansion {
    const entry = table.shorthands.get(name) orelse return null;
    if (entry.kind != .unmodelled) return null;
    if (cssWide(std.mem.trim(u8, value, &std.ascii.whitespace)) != null) return null;

    if (isColumns(entry)) {
        return expand(arena, .{
            .kind = .components,
            .longhands = entry.longhands,
            .fillers = &columns_fillers,
            .group = 2,
            .groups = 1,
        }, value);
    }

    if (isListStyle(entry)) {
        const expansion = try expand(arena, .{
            .kind = .components,
            .longhands = entry.longhands,
            .fillers = &list_style_fillers,
            .group = 3,
            .groups = 1,
        }, value) orelse return null;
        // `none` in a `list-style` is BOTH the type and the image, which is the
        // one thing the components rule cannot say -- it gives each component
        // one slot. Measured: `list-style: none` answers `list-style-type:
        // none` as well as `list-style-image: none`, and `list-style: none
        // inside` answers both plus `inside`.
        var components = Components.init(value);
        while (components.next()) |component| {
            if (!std.ascii.eqlIgnoreCase(component, "none")) continue;
            const values = @constCast(expansion.values);
            values[1] = "none";
            values[2] = "none";
            break;
        }
        return expansion;
    }

    if (isGridArea(entry)) return gridAreaExpand(arena, value);
    if (isGridLinePair(entry)) return gridLinePairExpand(arena, entry.longhands, value);

    if (isFontVariant(entry)) {
        const fillers = [_][]const u8{ "normal", "normal", "normal", "normal", "normal", "normal", "normal" };
        return expand(arena, .{
            .kind = .components,
            .longhands = entry.longhands,
            .fillers = &fillers,
            .group = 7,
            .groups = 1,
        }, value);
    }
    return null;
}

/// `<grid-line> [ / <grid-line> ]{0,3}`, and the omitted ones are not fillers:
/// a line left out copies an earlier one when that one is a custom ident, and
/// is `auto` otherwise. Measured over seven values
/// (scratch/b93/expr-grammar-truth.js): `grid-area: foo` answers `foo` on all
/// four, `grid-area: 1` answers `1` and three `auto`, and `grid-area: span 2`
/// answers `span 2` and three `auto` -- `span 2` is not an ident.
fn gridAreaExpand(arena: Allocator, value: []const u8) !?Expansion {
    var lines: [4][]const u8 = undefined;
    var count: usize = 0;
    var it = std.mem.splitScalar(u8, value, '/');
    while (it.next()) |raw| {
        const line = std.mem.trim(u8, raw, &std.ascii.whitespace);
        if (line.len == 0) return null;
        if (count == lines.len) return null;
        lines[count] = line;
        count += 1;
    }
    if (count == 0) return null;

    const values = try arena.alloc([]const u8, grid_area_longhands.len);
    values[0] = lines[0];
    values[1] = if (count > 1) lines[1] else gridLineFallback(lines[0]);
    values[2] = if (count > 2) lines[2] else gridLineFallback(lines[0]);
    values[3] = if (count > 3) lines[3] else gridLineFallback(values[1]);
    return .{ .names = &grid_area_longhands, .values = values };
}

/// What an omitted `<grid-line>` takes from the one it mirrors: the ident
/// itself, or `auto` when there is no ident to copy.
fn gridLineFallback(line: []const u8) []const u8 {
    return if (isGridIdent(line)) line else "auto";
}

/// A bare custom ident -- not `auto`, not a number, not `span <n>`.
fn isGridIdent(line: []const u8) bool {
    if (std.ascii.eqlIgnoreCase(line, "auto")) return false;
    if (std.mem.indexOfAny(u8, line, " \t\r\n") != null) return false;
    if (line.len == 0) return false;
    return !std.ascii.isDigit(line[0]) and line[0] != '-' and line[0] != '+';
}

/// `columns` as Chrome writes it: the components that are not `auto`, width
/// first whatever order the author used, and `auto` when neither is set.
/// Measured: `columns: 3 100px` reads back `100px 3`, `columns: 3` reads back
/// `3`, `columns: auto` reads back `auto`.
fn columnsJoin(arena: Allocator, values: []const []const u8) ![]const u8 {
    const width_set = !std.ascii.eqlIgnoreCase(values[0], "auto");
    const count_set = !std.ascii.eqlIgnoreCase(values[1], "auto");
    if (width_set and count_set) return std.mem.concat(arena, u8, &.{ values[0], " ", values[1] });
    if (width_set) return values[0];
    if (count_set) return values[1];
    return "auto";
}

/// `list-style` as Chrome writes it. A computed view writes all three in
/// longhand order (`outside none square`); a declaration writes only the
/// components that are off their initial value, and `list-style: none` writes
/// the single `none` its type carries.
fn listStyleJoin(arena: Allocator, values: []const []const u8, keep_all: bool) ![]const u8 {
    if (keep_all) {
        return std.mem.concat(arena, u8, &.{ values[0], " ", values[1], " ", values[2] });
    }
    var written: [3][]const u8 = undefined;
    var count: usize = 0;
    for (values, list_style_fillers) |held, filler| {
        if (std.ascii.eqlIgnoreCase(held, filler)) continue;
        written[count] = held;
        count += 1;
    }
    if (count == 0) return "";
    return std.mem.join(arena, " ", written[0..count]);
}

/// `grid-area` as Chrome writes it: the four lines, slash-separated, with the
/// trailing ones dropped while they hold exactly what leaving them out would
/// have produced.
fn gridAreaJoin(arena: Allocator, values: []const []const u8) ![]const u8 {
    var count: usize = 4;
    if (std.ascii.eqlIgnoreCase(values[3], gridLineFallback(values[1]))) count = 3;
    if (count == 3 and std.ascii.eqlIgnoreCase(values[2], gridLineFallback(values[0]))) count = 2;
    if (count == 2 and std.ascii.eqlIgnoreCase(values[1], gridLineFallback(values[0]))) count = 1;
    return std.mem.join(arena, " / ", values[0..count]);
}

/// `<grid-line> [ / <grid-line> ]?`. Same fallback as `grid-area`'s: an omitted
/// end copies the start when the start is a bare custom ident, `auto`
/// otherwise. Measured over seventeen shapes
/// (css/grid_line_shorthands.html): `grid-row: foo` is `foo / foo`,
/// `grid-row: 2` is `2 / auto`, `grid-column: span 2` is `span 2 / auto`.
fn gridLinePairExpand(arena: Allocator, longhands: []const []const u8, value: []const u8) !?Expansion {
    var lines: [2][]const u8 = undefined;
    var count: usize = 0;
    var it = std.mem.splitScalar(u8, value, '/');
    while (it.next()) |raw| {
        const line = std.mem.trim(u8, raw, &std.ascii.whitespace);
        if (line.len == 0) return null;
        if (count == lines.len) return null;
        lines[count] = line;
        count += 1;
    }
    if (count == 0) return null;

    const values = try arena.alloc([]const u8, 2);
    values[0] = lines[0];
    values[1] = if (count > 1) lines[1] else gridLineFallback(lines[0]);
    return .{ .names = longhands, .values = values };
}

/// The end is dropped when it holds what an omitted one would have held --
/// which is why `3 / auto` reads `3` and `3 / 3` reads `3 / 3`: a number is not
/// an ident, so its omitted form is `auto`. Only the end is ever dropped, so
/// `auto / 4` keeps both.
fn gridLinePairJoin(arena: Allocator, values: []const []const u8) ![]const u8 {
    if (std.ascii.eqlIgnoreCase(values[1], gridLineFallback(values[0]))) {
        return arena.dupe(u8, values[0]);
    }
    return std.mem.join(arena, " / ", values[0..2]);
}

const font_variant_longhands = [_][]const u8{
    "font-variant-ligatures", "font-variant-caps",       "font-variant-alternates",
    "font-variant-numeric",   "font-variant-east-asian", "font-variant-position",
    "font-variant-emoji",
};

fn isFontVariant(entry: Shorthand) bool {
    return entry.kind == .unmodelled and
        entry.longhands.len == 7 and
        std.mem.eql(u8, entry.longhands[0], "font-variant-ligatures");
}

/// `font-variant` is seven longhands, each holding `normal` until a keyword
/// that only IT accepts arrives -- there is no order to get wrong and no
/// filler to guess, so the components rule reproduces it once the fillers are
/// known. Measured (scratch/b93/expr-grammar-join.js): `font-variant:
/// small-caps tabular-nums` leaves caps and numeric holding those two and the
/// other five `normal`, and reads back as the two of them in longhand order.
///
/// It matters through `font`, not through itself: `font: italic small-caps
/// bold 16px/2 serif` already stored `font-variant-caps: small-caps` here, and
/// `font-variant` read back `normal` because it had no way to see it.
fn fontVariantJoin(arena: Allocator, values: []const []const u8) ![]const u8 {
    var written: [7][]const u8 = undefined;
    var count: usize = 0;
    for (values) |held| {
        if (held.len == 0 or std.ascii.eqlIgnoreCase(held, "normal")) continue;
        written[count] = held;
        count += 1;
    }
    if (count == 0) return "normal";
    return std.mem.join(arena, " ", written[0..count]);
}
